#!/usr/bin/env bash
# site-host: embed, native tests, the wasm32-wasip2 component, then the end-to-end run under real
# `wasmtime serve` inside a network namespace that has loopback only (the cold-start proof).
#
#   scripts/build-and-test.sh <release dir named by its CID>
#
# Offline: every crate comes from the local cargo cache; nothing is downloaded. Run it through the shared queue.
set -euo pipefail
cd "$(dirname "$0")/.."
REL="$(realpath "${1:?usage: build-and-test.sh <release dir>}")"
export CARGO_NET_OFFLINE=true CARGO_BUILD_JOBS=4

# src/bindings.rs is checked in, generated by:
#   wit-bindgen rust --generate-all --runtime-path wit_bindgen_rt --world site-host --out-dir <dir> wit   (0.41.0)
echo "== embed"
node scripts/embed-release.mjs --release "$REL"

mkdir -p target
echo "== native tests (the component's own verification and routing code)"
cargo test --offline --lib --tests 2>&1 | tee target/native-test.log
grep -q "test result: ok" target/native-test.log
if grep -q "test result: FAILED" target/native-test.log; then echo "native tests FAILED"; exit 1; fi

echo "== component"
cargo build --offline --release --target wasm32-wasip2
WASM=target/wasm32-wasip2/release/site_host.wasm
wasm-tools validate --features all "$WASM"
wasm-tools component wit "$WASM" > target/component.wit
sha256sum "$WASM" release/site.car release/release.json src/*.rs wit/world.wit Cargo.toml Cargo.lock

echo "== end to end, inside a loopback-only network namespace"
unshare -rn sh -c "ip link set lo up && SITE_HOST_NETNS=1 SITE_HOST_WASM='$PWD/$WASM' SITE_RELEASE_DIR='$REL' node --test --test-concurrency=1 test/e2e.mjs"
echo "SITE-HOST-BUILD-AND-TEST-OK"
